if (existsSync(revocation)) {
  // Invalid markers also fail closed; no protector/decryption call occurs.
  try {
    const stat = lstatSync(revocation)
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 512) return undefined
    const marker = JSON.parse(readFileSync(revocation, 'utf8'))
    if (marker.format !== 1 || marker.connectionId !== connectionId || marker.reason !== 'restored-deletion') return undefined
  } catch { return undefined }
  return undefined
}

// Only a genuinely absent marker permits decryption; dangling links and I/O errors do not.
try {
  const stat = lstatSync(revocation, { throwIfNoEntry: false })
  if (stat) {
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 512) return undefined
    const marker = JSON.parse(readFileSync(revocation, 'utf8'))
    if (marker.format !== 1 || marker.connectionId !== connectionId || marker.reason !== 'restored-deletion') return undefined
    return undefined
  }
} catch { return undefined }
